from pathlib import Path, PurePosixPath
from typing import Any, Iterator

ROOT = Path(__file__).resolve().parents[1]
DEFAULT_DB_DIR = Path(
    "Z:/SteamLibrary/steamapps/common/Football Manager 2024/data/database/db/2430/2430_fm"
)
ZSTD_MAGIC = bytes.fromhex("28b52ffd")
FMF_MAGIC = bytes.fromhex("0201666d662e080000")
DAT_MAGIC = b"\x03\x01tad."
MAX_DIRECTORY_SIZE = 16 * 1024 * 1024
MAX_ENTRY_SIZE = 256 * 1024 * 1024
MAX_STRING_SIZE = 1024 * 1024

# These are evidence-weighted hypotheses, not a recovered table-type enum.
